document.addEventListener('keydown',e=>{if(root.hidden||!root.isConnected||!isPPTChat())return;const dialog=root.querySelector('.st-dialog-back');if(dialog){if(e.key==='Escape')dismiss();if(e.key==='Tab'){const items=[...dialog.querySelectorAll('button,input,textarea')];if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus()}}return}if(e.key==='Escape'&&workspaceExpanded){e.preventDefault();setWorkspaceExpanded(false);return}if(e.key==='Tab'&&workspaceExpanded){const items=[...root.querySelectorAll('.st-expanded button:not(:disabled),.st-expanded input,.st-expanded textarea,.st-expanded select,.st-expanded summary,.st-expanded [contenteditable=true]')].filter(x=>x.getClientRects().length);if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0]?.focus()}}const typing=e.target.matches('input,textarea,select')||e.target.isContentEditable;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();save();return}if(typing)return;if(e.key==='Escape'){if(view==='play'){view=playReturn;redraw()}else if(view==='editor')closeEditor();else if(view==='browse')chat();return}if(view==='editor'&&(e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();root.querySelector(`[data-do="${e.shiftKey?'redo':'undo'}"]`)?.click()}if(['play','browse'].includes(view)&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();page=clamp(page+(e.key==='ArrowRight'?1:-1),0,deck.slides.length-1);redraw()}if(view==='editor'&&selected&&['Delete','Backspace'].includes(e.key)){e.preventDefault();root.querySelector('[data-do="delete"]')?.click()}});
